// Obtener el output del LLM (Gemini)
const raw = $input.item.json.output || '';
let cleaned = raw.trim()
  .replace(/^```json\s*/i, '')
  .replace(/^```\s*/i, '')
  .replace(/\s*```$/i, '')
  .trim();

let parsed;
try {
  parsed = JSON.parse(cleaned);
} catch (e) {
  return [{
    json: {
      parsed: { accion: 'error' },
      chatId: $('Telegram Trigger').first().json.message.chat.id,
      messageId: $('Telegram Trigger').first().json.message.message_id,
      error: 'JSON inválido del LLM: ' + e.message
    }
  }];
}

// Lista de acciones válidas
const validActions = ['modificar_plato', 'porcentaje', 'crear_promo', 'borrar_promo', 'agregar_plato', 'error'];
if (!validActions.includes(parsed.accion)) {
  parsed.accion = 'error';
}

// ========================================
// FUNCIÓN MEJORADA: Title Case perfecto (maneja acentos)
// ========================================
function toTitleCase(str) {
  if (!str || typeof str !== 'string') return str;
  return str
    .toLowerCase()                  // Todo a minúscula primero
    .normalize("NFD")                // Separa acentos (para que café → cafe + ´)
    .replace(/[\u0300-\u036f]/g, "") // Elimina acentos temporales (opcional si querés sin acentos)
    .replace(/\b\w/g, char => char.toUpperCase()); // Primera letra de cada palabra mayúscula
}

// Ejemplos de cómo funciona:
// "cafeteria" → "Cafeteria"
// "CAFETERIA" → "Cafeteria"
// "postres" → "Postres"
// "desayuno clásico" → "Desayuno Clásico"

// ========================================
// Validaciones por acción
// ========================================

if (parsed.accion === 'modificar_plato') {
  if (!parsed.plato) {
    parsed.accion = 'error';
  } else {
    parsed.plato = parsed.plato.toLowerCase().trim();

    const tieneModificacion = parsed.precio || parsed.descripcion || parsed.nuevo_nombre || parsed.categoria;
    if (!tieneModificacion) {
      parsed.accion = 'error';
    }

    if (parsed.descripcion) parsed.descripcion = parsed.descripcion.trim();
    if (parsed.nuevo_nombre) parsed.nuevo_nombre = parsed.nuevo_nombre.toLowerCase().trim();
    if (parsed.precio && (typeof parsed.precio !== 'number' || parsed.precio <= 0)) {
      parsed.accion = 'error';
    }
  }
}

if (parsed.accion === 'porcentaje') {
  if (!parsed.categoria || typeof parsed.porcentaje !== 'number') {
    parsed.accion = 'error';
  }
}

if (parsed.accion === 'crear_promo') {
  if (!parsed.texto || parsed.texto.trim() === '') {
    parsed.accion = 'error';
  }
  parsed.color = (parsed.color || 'blue').replace('#', '');
}

if (parsed.accion === 'agregar_plato') {
  if (!parsed.plato || typeof parsed.precio !== 'number' || !parsed.categoria) {
    parsed.accion = 'error';
  } else {
    parsed.plato = parsed.plato.toLowerCase().trim();
    if (parsed.descripcion) parsed.descripcion = parsed.descripcion.trim();
  }
}

// ========================================
// NORMALIZAR CATEGORÍA: Siempre Title Case perfecto
// ========================================
if (['modificar_plato', 'porcentaje', 'agregar_plato'].includes(parsed.accion) && parsed.categoria) {
  parsed.categoria = toTitleCase(parsed.categoria.trim());
}

// ========================================
// MAPEO DE CATEGORÍAS A NOMBRES EXACTOS EN DB
// ========================================
if (['modificar_plato', 'porcentaje', 'agregar_plato'].includes(parsed.accion) && parsed.categoria) {
  const categoriaMap = {
    'Cafeteria': 'Cafeteria',
    'Coffee': 'Cafeteria',
    'Cafe': 'Cafeteria',
    'Café': 'Cafeteria',
    'Cafes': 'Cafeteria',
    'Bebidas': 'Cafeteria',
    'Bebida': 'Cafeteria',
    'Postres': 'Postres',
    'Postre': 'Postres',
    'Pasteleria': 'Postres',
    'Dulces': 'Postres',
    'Desayuno': 'Desayuno',
    'Desayunos': 'Desayuno',
    'Breakfast': 'Desayuno',
    'Merienda': 'Desayuno',
    'Desayunos Y Meriendas': 'Desayunos Y Meriendas',
    'Pizzas': 'Pizzas',
    'Pizza': 'Pizzas'
  };

  parsed.categoria = categoriaMap[parsed.categoria] || parsed.categoria;
}

// ========================================
// RETURN FINAL
// ========================================
return [{
  json: {
    parsed: parsed,
    chatId: $('Telegram Trigger').first().json.message.chat.id,
    messageId: $('Telegram Trigger').first().json.message.message_id,
    username: $('Telegram Trigger').first().json.message?.from?.username || 'unknown',
    tenant_id: $('Code: Set Tenant Context').first()?.json?.tenant_id || null  // Seguro contra null
  }
}];

