// Validar que tengamos todos los datos necesarios
const switchData = $input.first().json;
const parsed = switchData.parsed;
const chatId = switchData.chatId;
const messageId = switchData.messageId;
const tenantId = switchData.tenant_id;

// Validar campos requeridos
if (!parsed.plato || !parsed.precio || !parsed.categoria) {
  return {
    json: {
      error: true,
      chatId: chatId,
      messageId: messageId,
      mensaje: 'Faltan datos: necesito nombre del plato, precio y categoría'
    }
  };
}

// Normalizar datos
const plato = parsed.plato.toLowerCase().trim();
const categoria = parsed.categoria.trim();
const precio = parseFloat(parsed.precio);
const descripcion = parsed.descripcion || null;

return {
  json: {
    plato: plato,
    precio: precio,
    categoria: categoria,
    descripcion: descripcion,
    chatId: chatId,
    messageId: messageId,
    tenant_id: tenantId
  }
};

// Obtener resultados de Supabase
const results = $input.all();

// Obtener datos del nodo Validate para pasarlos (esto está perfecto)
const validateData = $('Code: Validate Nuevo Plato').first().json;

// --- NUEVA LÓGICA DE COMPROBACIÓN ---
// Comprobamos no solo si hay un resultado, sino si ese resultado tiene datos reales de la base de datos.
// Usamos 'id' como ejemplo, ya que toda fila de Supabase debería tenerlo.
// Si el nodo Supabase no encontró nada, 'results[0].json.id' será null o undefined.
if (results.length > 0 && results[0].json.id != null) {
  // El plato YA EXISTE
  return [{
    json: {
      platoExists: true,
      existingPlato: results[0].json,
      // Pasamos los datos originales para mantener el contexto
      plato: validateData.plato,
      precio: validateData.precio,
      categoria: validateData.categoria,
      descripcion: validateData.descripcion,
      chatId: validateData.chatId,
      messageId: validateData.messageId,
      tenant_id: validateData.tenant_id // Asegúrate de pasar el tenant_id también
    }
  }];
} else {
  // El plato NO EXISTE - OK para crear
  return [{
    json: {
      platoExists: false,
      // Pasamos los datos originales para el siguiente paso
      plato: validateData.plato,
      precio: validateData.precio,
      categoria: validateData.categoria,
      descripcion: validateData.descripcion,
      chatId: validateData.chatId,
      messageId: validateData.messageId,
      tenant_id: validateData.tenant_id // Y aquí también
    }
  }];
}

// Obtener el mensaje del usuario
//const mensaje = $input.first().json.message.text.toLowerCase().trim();

const mensaje = $input.first().json.originalMessage.toLowerCase().trim();

// Función para detectar palabras clave
function contiene(texto, palabras) {
  return palabras.some(palabra => texto.includes(palabra));
}

// CATEGORÍA 1: HELP/AYUDA
const palabrasHelp = [
  'ayuda', 'help', 'cómo puedo?', 'como podria?', 'comandos', 
  'qué puedo', 'que puedo', 'instrucciones', 
  'guía', 'guia', 'opciones', 'qué hago', 'que hago'
];

if (contiene(mensaje, palabrasHelp)) {
  return [{
    json: {
      intent: 'help',
      originalMessage: mensaje,
      chatId: $input.first().json.message.chat.id,
      messageId: $input.first().json.message.message_id
    }
  }];
}

// CATEGORÍA 2: PALABRAS TÉCNICAS (indica comando)
const palabrasTecnicas = [
  'subir', 'subí', 'subi', 'bajar', 'bajá', 'baja',
  'precio', 'promo', 'categoría', 'categoria', 'Categoria', 'Categoría',
  'plato', 'menú', 'menu', 'agregar', 'agregá', 'agrega',
  'eliminar', 'eliminá', 'elimina', 'borrar', 'borrá', 'borra',
  'cambiar', 'cambiá', 'cambia', 'actualizar', 'actualizá', 'actualiza',
  'poner', 'poné', 'pone', 'sacar', 'sacá', 'saca',
  'crear', 'creá', 'crea', '%', 'pesos', '$'
];

const tieneTecnicas = contiene(mensaje, palabrasTecnicas);

// CATEGORÍA 3: SOCIAL PURO (solo si NO tiene palabras técnicas)
const palabrasSociales = [
  'hola', 'buenas', 'buen día', 'buen dia', 'hey', 'qué tal', 'que tal',
  'chau', 'adiós', 'adios', 'gracias', 'hasta luego',
  'cómo estás', 'como estas', 'todo bien', 'qué hacés', 'que haces',
  'che', 'ey', 'hi', 'hello', 'como estas?', 'como va?'
];

if (!tieneTecnicas && contiene(mensaje, palabrasSociales)) {
  return [{
    json: {
      intent: 'social',
      originalMessage: mensaje,
      chatId: $input.first().json.message.chat.id,
      messageId: $input.first().json.message.message_id
    }
  }];
}

// CATEGORÍA 4: COMANDO (default - todo lo demás)
return [{
  json: {
    intent: 'comando',
    originalMessage: mensaje,
    chatId: $input.first().json.message.chat.id,
    messageId: $input.first().json.message.message_id
  }
}];

// Nodo: "Code: Build Update"
const platoActual = $input.item.json;
const parsed = $('Code: Parse & Validate').item.json.parsed;

// Construir array de campos a actualizar
const fieldsToUpdate = [];

if (parsed.precio !== undefined) {
  fieldsToUpdate.push({
    fieldId: 'precio',
    fieldValue: parsed.precio
  });
}

if (parsed.nuevo_nombre) {
  fieldsToUpdate.push({
    fieldId: 'nombre',
    fieldValue: parsed.nuevo_nombre
  });
}

if (parsed.descripcion) {
  fieldsToUpdate.push({
    fieldId: 'descripcion', 
    fieldValue: parsed.descripcion
  });
}

if (parsed.categoria) {
  fieldsToUpdate.push({
    fieldId: 'categoria',
    fieldValue: parsed.categoria
  });
}

return [{
  json: {
    id: platoActual.id,
    nombre: platoActual.nombre,
    fieldsToUpdate: fieldsToUpdate,
    parsed: parsed
  }
}];

// Obtener datos
const botData = $('Supabase: Get Tenant from Bot').first().json;
const chatId = $('Telegram Trigger').first().json.message.chat.id.toString();

// Verificar si el chat_id está en la lista de admins
const adminChatIds = botData.admin_chat_ids || [];
const isAdmin = adminChatIds.includes(chatId);

// Devolver el resultado con contexto completo
return [{
  json: {
    isAdmin: isAdmin,
    tenant_id: botData.tenant_id,
    admin_chat_ids: adminChatIds,
    chatId: chatId,
    messageId: $('Telegram Trigger').first().json.message.message_id,
    originalMessage: $('Telegram Trigger').first().json.message.text,
    from: $('Telegram Trigger').first().json.message.from
  }
}];

// Obtener datos del admin check
const adminData = $input.first().json;

// Preparar contexto completo para el resto del workflow
return [{
  json: {
    tenant_id: adminData.tenant_id,
    isAdmin: true,
    chatId: adminData.chatId,
    messageId: adminData.messageId,
    originalMessage: adminData.originalMessage,
    username: adminData.from?.username || 'unknown',
    message: {
      text: adminData.originalMessage,
      chat: {
        id: adminData.chatId
      },
      message_id: adminData.messageId,
      from: adminData.from
    }
  }
}];

const data = $input.first().json;

// Capitalizar primera letra
function capitalize(str) {
  return str.charAt(0).toUpperCase() + str.slice(1).toLowerCase();
}

return [{
  json: {
    ...data,
    parsed: {
      ...data.parsed,
      plato: capitalize(data.parsed.plato)
    }
  }
}];

// Los items que vienen de Supabase (los platos de la categoría)
const items = $input.all();

if (!items.length) {
  return []; // Si no hay platos, no hacer nada
}

// Obtener contexto del mensaje original (del Switch)
const switchData = $('Switch: Route Actions').first().json;

const porcentaje = switchData.parsed.porcentaje;
const categoria = switchData.parsed.categoria;
const chatId = switchData.chatId;
const messageId = switchData.messageId;

// Verificar que tengamos el porcentaje (seguridad)
if (typeof porcentaje !== 'number') {
  return [{ json: { error: 'Porcentaje inválido' } }];
}

// DEBUG: Ver qué platos llegaron
console.log('=== DEBUG PLATOS ===');
items.forEach((item, index) => {
  console.log(`Plato ${index + 1}:`, item.json);
  console.log('Precio actual del plato:', item.json.precio);
});

// Calcular nuevos precios para CADA plato
const updates = items.map(item => {
  const plato = item.json; // ← El plato actual de este item

  const precioActual = parseFloat(plato.price) || 0;
  const precioNuevo = Math.round(precioActual * (1 + porcentaje / 100));

  // DEBUG: Ver cálculo por plato
  console.log(`Calculo para ${plato.nombre}: Actual ${precioActual} → Nuevo ${precioNuevo}`);

  return {
    json: {
      id: plato.id,
      nombre: plato.nombre,
      precioActual: precioActual,
      precioNuevo: precioNuevo,
      categoria: categoria,
      porcentaje: porcentaje,
      chatId: chatId,
      messageId: messageId
    }
  };
});

return updates;

// --- Configuración ---
// Si los nombres de los campos de precio del nodo anterior son diferentes, ajústalos aquí.
const campoPrecioViejo = 'precio_anterior'; // Ejemplo
const campoPrecioNuevo = 'precio_nuevo';   // Ejemplo

// --- Lógica del Nodo ---
const items = $input.all();
const total = items.length;

// Si no hay items, no hagas nada.
if (total === 0) {
  return [{ json: { total: 0, detalles: 'No se actualizó ningún producto.' } }];
}

const first = items[0].json;

// Extraer datos del nodo de parseo inicial
const categoria = $('Code: Parse & Validate').item.json.parsed.categoria;
const porcentaje = $('Code: Parse & Validate').item.json.parsed.porcentaje;

// Generar la lista de detalles usando los nombres de campo correctos
const detalles = items.slice(0, 5).map(i => {
  const nombre = i.json.name; // Usar 'name' en lugar de 'nombre'
  const precioViejo = i.json[campoPrecioViejo];
  const precioNuevo = i.json[campoPrecioNuevo];
  return `• ${nombre}: $${precioViejo} → $${precioNuevo}`;
}).join('\n');

const mas = total > 5 ? `\n... y ${total - 5} más` : '';

// Retornar todos los datos necesarios
return [{
  json: {
    // Datos para el resumen
    total,
    categoria,
    porcentaje,
    detalles: detalles + mas,

    // IDs importantes para el contexto
    tenant_id: first.tenant_id,
    category_id: first.category_id,

    // IDs para la respuesta de Telegram
    chatId: first.chatId,
    messageId: first.messageId
  }
}];

// Debug: Ver qué está llegando exactamente
const categoria = $json.parsed.categoria;

console.log('=== DEBUG CATEGORIA ===');
console.log('Categoria recibida:', categoria);
console.log('Tipo:', typeof categoria);
console.log('Longitud:', categoria.length);

// Mapeo de nombres del LLM a nombres reales en DB
const categoriaMap = {
  'coffee': 'Cafetería',        // ← Ajusta con el nombre REAL de tu DB
  'pastry': 'Postres',
  'classic break': 'Desayuno',
  'pizzas': 'Pizzas',
  'desayunos y meriendas': 'Desayunos y Meriendas'
};

// Limpiar y mapear
const categoriaLimpia = categoria.trim();
const categoriaMapeada = categoriaMap[categoriaLimpia] || categoria;

console.log('Categoria mapeada:', categoriaMapeada);

return {
  json: {
    ...$json,
    parsed: {
      ...$json.parsed,
      categoria: categoriaMapeada  // ← Usar el nombre mapeado
    }
  }
};

